{
  "name": "crucible-sketch-dashboard",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 127.0.0.1",
    "build": "tsc -b && vite build",
    "preview": "vite preview --host 127.0.0.1"
  },
  "dependencies": {
    "@vitejs/plugin-react": "^5.0.0",
    "lucide-react": "^0.468.0",
    "vite": "^5.4.11",
    "typescript": "^5.6.3",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {}
}

:root {
  color: #263238;
  background: #f6f0df;
  font-family: "Segoe UI", "Microsoft YaHei", system-ui, sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --ink: #263238;
  --muted: #69757d;
  --paper: #fff9e9;
  --paper-deep: #f7edce;
  --line: rgba(45, 57, 64, 0.34);
  --blue: #8ecae6;
  --yellow: #ffd166;
  --green: #90d7a7;
  --pink: #ff8fab;
  --accent: #ff6b35;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    linear-gradient(rgba(70, 100, 130, 0.08) 1px, transparent 1px) 0 0 / 100% 32px,
    linear-gradient(90deg, rgba(70, 100, 130, 0.05) 1px, transparent 1px) 0 0 / 32px 100%,
    radial-gradient(circle at 20% 20%, rgba(255, 209, 102, 0.18), transparent 28%),
    #f6f0df;
}

button {
  color: inherit;
  font: inherit;
}

.app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 24px;
  min-height: 100vh;
  padding: 24px;
}

.sketch-panel,
.sketch-card {
  position: relative;
  border: 2px solid var(--ink);
  background: var(--paper);
  box-shadow: 8px 8px 0 rgba(38, 50, 56, 0.16);
}

.sketch-panel::before,
.sketch-card::before {
  content: "";
  position: absolute;
  inset: 5px -4px -5px 4px;
  z-index: -1;
  border: 1.5px dashed rgba(38, 50, 56, 0.28);
  transform: rotate(-0.35deg);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 28px;
  height: calc(100vh - 48px);
  padding: 24px 18px;
  transform: rotate(-0.25deg);
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-sigil {
  display: grid;
  width: 54px;
  height: 54px;
  place-items: center;
  border: 2px solid var(--ink);
  background: #cdeffd;
  box-shadow: 4px 4px 0 rgba(38, 50, 56, 0.2);
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-size: 31px;
  font-weight: 800;
  transform: rotate(-4deg);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-size: 30px;
}

h2 {
  max-width: 780px;
  margin-bottom: 0;
  font-size: clamp(26px, 3vw, 46px);
  line-height: 1.08;
  letter-spacing: 0;
}

h3 {
  margin-bottom: 0;
  font-size: 20px;
}

.bookmark-nav {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.bookmark {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 46px;
  padding: 0 14px;
  border: 2px solid var(--ink);
  background: #fffdf4;
  cursor: pointer;
  transform: rotate(var(--tilt));
  transition: transform 180ms ease, background 180ms ease, box-shadow 180ms ease;
}

.bookmark:hover,
.bookmark.active {
  background: linear-gradient(transparent 48%, rgba(255, 209, 102, 0.78) 48%);
  box-shadow: 4px 4px 0 rgba(38, 50, 56, 0.17);
  transform: rotate(0deg) translateX(4px);
}

.mini-note {
  position: relative;
  margin-top: auto;
  padding: 22px 16px 16px;
  background: #fff2a8;
  border: 2px solid var(--ink);
  transform: rotate(1.5deg);
}

.mini-note strong,
.mini-note span {
  display: block;
}

.mini-note span {
  margin-top: 8px;
  color: var(--muted);
  font-size: 13px;
}

.note-pin {
  position: absolute;
  top: -10px;
  left: 50%;
  width: 18px;
  height: 18px;
  border: 2px solid var(--ink);
  border-radius: 999px;
  background: var(--pink);
}

.workspace {
  min-width: 0;
}

.topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.topbar-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.marker-button,
.icon-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 2px solid var(--ink);
  background: #fffdf4;
  min-height: 42px;
  padding: 0 14px;
  cursor: pointer;
  box-shadow: 4px 4px 0 rgba(38, 50, 56, 0.16);
  transition: transform 180ms ease, background 180ms ease;
}

.marker-button.primary {
  background: #ffb36c;
}

.marker-button:hover,
.icon-chip:hover {
  background: linear-gradient(transparent 45%, rgba(142, 202, 230, 0.8) 45%);
  transform: rotate(-1deg) translateY(-2px);
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 18px;
}

.sketch-card {
  padding: 18px;
  animation: draw-in 520ms ease both, gentle-wobble 7s ease-in-out infinite;
  animation-delay: var(--delay, 0ms), calc(var(--delay, 0ms) + 900ms);
}

.metric-card {
  min-height: 152px;
}

.card-head,
.section-title,
.source-meta,
.source-foot,
.link-row,
.status-strip {
  display: flex;
  align-items: center;
}

.card-head,
.section-title,
.source-meta {
  justify-content: space-between;
  gap: 14px;
}

.sketch-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 2px solid var(--ink);
  background: #fff;
  transform: rotate(-5deg);
}

.metric-delta {
  padding: 5px 8px;
  background: rgba(255, 255, 255, 0.58);
  border: 1px solid rgba(38, 50, 56, 0.32);
  font-size: 12px;
  font-weight: 800;
}

.hand-number {
  display: block;
  margin-top: 18px;
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-size: 42px;
  line-height: 1;
  letter-spacing: 0;
}

.metric-card p {
  margin: 7px 0 0;
  color: var(--muted);
  font-weight: 700;
}

.tone-blue {
  background: linear-gradient(155deg, #fffdf4, #d9f2fb);
}

.tone-yellow {
  background: linear-gradient(155deg, #fffdf4, #ffe59d);
}

.tone-green {
  background: linear-gradient(155deg, #fffdf4, #dbf6e3);
}

.tone-pink {
  background: linear-gradient(155deg, #fffdf4, #ffd7e0);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(300px, 0.85fr);
  gap: 18px;
  align-items: stretch;
}

.hero-board {
  min-height: 360px;
}

.source-list {
  display: grid;
  gap: 14px;
  margin-top: 18px;
}

.source-row {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  border: 1.8px solid rgba(38, 50, 56, 0.62);
  background: rgba(255, 255, 255, 0.52);
  transform: rotate(-0.25deg);
}

.source-row:nth-child(2) {
  transform: rotate(0.35deg);
}

.source-type {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 2px solid var(--ink);
  background: var(--blue);
}

.source-type.audio {
  background: var(--green);
}

.source-type.document {
  background: var(--yellow);
}

.source-main {
  min-width: 0;
}

.source-meta strong,
.source-foot span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.source-meta strong {
  min-width: 0;
}

.source-meta span,
.source-foot {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

.pencil-progress {
  height: 13px;
  margin: 10px 0;
  border: 2px solid var(--ink);
  background: repeating-linear-gradient(-12deg, #fffdf4 0 7px, #f4e8c5 7px 12px);
}

.pencil-progress span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, #8ecae6, #ffb36c);
  animation: pencil-fill 900ms ease both;
}

.source-foot {
  justify-content: space-between;
  gap: 10px;
}

.chart-card,
.graph-card,
.note-card,
.timeline-card,
.model-card {
  min-height: 290px;
}

.chart-bars {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  align-items: end;
  gap: 14px;
  height: 218px;
  margin-top: 22px;
  padding: 16px 10px 0;
  background:
    linear-gradient(rgba(38, 50, 56, 0.12) 1px, transparent 1px) 0 0 / 100% 42px;
}

.bar-wrap {
  display: grid;
  grid-template-rows: 1fr auto;
  align-items: end;
  height: 100%;
  text-align: center;
}

.bar {
  display: block;
  width: 100%;
  max-width: 34px;
  margin: 0 auto;
  border: 2px solid var(--ink);
  background: #8ecae6;
  box-shadow: 3px 3px 0 rgba(38, 50, 56, 0.16);
  animation: grow-up 760ms ease both;
  animation-delay: var(--delay);
}

.bar-wrap:nth-child(3n) .bar {
  background: #ffd166;
}

.bar-wrap:nth-child(4n) .bar {
  background: #90d7a7;
}

.bar-wrap small {
  margin-top: 8px;
  font-weight: 800;
}

.link-stack {
  display: grid;
  gap: 13px;
  margin-top: 20px;
}

.link-row {
  gap: 10px;
  padding: 10px 8px;
  background: rgba(255, 255, 255, 0.5);
  border-bottom: 2px solid rgba(38, 50, 56, 0.16);
}

.link-row i {
  flex: 1;
  height: 8px;
  background-image: radial-gradient(var(--ink) 1.5px, transparent 1.5px);
  background-size: 10px 8px;
}

.link-row strong {
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  color: #d94d2b;
  font-size: 21px;
}

.markdown-paper {
  margin-top: 18px;
  padding: 16px;
  min-height: 195px;
  border-left: 4px solid #ff8fab;
  background:
    linear-gradient(rgba(70, 100, 130, 0.12) 1px, transparent 1px) 0 14px / 100% 28px,
    #fffefa;
}

.markdown-paper p {
  margin-bottom: 14px;
  line-height: 1.65;
}

.md-heading {
  font-weight: 900;
}

mark {
  padding: 1px 5px;
  background: #ffd166;
}

.tag-row {
  color: #2b7a78;
  font-weight: 800;
}

.timeline {
  display: grid;
  gap: 12px;
  margin: 18px 0 0;
  padding: 0;
  list-style: none;
}

.timeline li {
  display: grid;
  grid-template-columns: 58px 1fr;
  gap: 12px;
}

.timeline time {
  align-self: start;
  padding: 5px 7px;
  border: 2px solid var(--ink);
  background: #d9f2fb;
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-weight: 800;
}

.timeline strong,
.timeline span {
  display: block;
}

.timeline span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
}

.model-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 18px;
}

.model-grid div {
  padding: 12px;
  border: 2px solid rgba(38, 50, 56, 0.5);
  background: rgba(255, 255, 255, 0.42);
}

.model-grid span,
.model-grid strong {
  display: block;
}

.model-grid span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.model-grid strong {
  margin-top: 4px;
  overflow-wrap: anywhere;
}

.status-strip {
  gap: 9px;
  margin-top: 16px;
  padding: 12px;
  background: #dff5e6;
  border: 2px solid rgba(38, 50, 56, 0.52);
  font-weight: 800;
}

@keyframes draw-in {
  from {
    opacity: 0;
    clip-path: inset(0 100% 0 0);
    transform: translateY(10px) rotate(-0.5deg);
  }
  to {
    opacity: 1;
    clip-path: inset(0 0 0 0);
    transform: translateY(0) rotate(0deg);
  }
}

@keyframes gentle-wobble {
  0%,
  100% {
    rotate: 0deg;
  }
  50% {
    rotate: 0.25deg;
  }
}

@keyframes grow-up {
  from {
    transform: scaleY(0.05);
    transform-origin: bottom;
  }
  to {
    transform: scaleY(1);
    transform-origin: bottom;
  }
}

@keyframes pencil-fill {
  from {
    width: 0;
  }
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    height: auto;
  }

  .bookmark-nav {
    display: grid;
    grid-template-columns: repeat(5, minmax(120px, 1fr));
  }

  .mini-note {
    margin-top: 0;
  }

  .metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .app-shell {
    padding: 14px;
  }

  .topbar,
  .section-title {
    flex-direction: column;
    align-items: stretch;
  }

  .topbar-actions {
    justify-content: flex-start;
  }

  .bookmark-nav,
  .metric-grid,
  .dashboard-grid,
  .model-grid {
    grid-template-columns: 1fr;
  }

  .source-row {
    grid-template-columns: 1fr;
  }

  .source-foot {
    align-items: flex-start;
    flex-direction: column;
  }
}

{
  "compilerOptions": {
    "composite": true,
    "skipLibCheck": true,
    "module": "ESNext",
    "moduleResolution": "Node",
    "allowSyntheticDefaultImports": true
  },
  "include": ["vite.config.ts"]
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    strictPort: false
  }
});

