  align-items: center;
  gap: 7px;
  font-weight: 900;
}

.panel-title button,
.tab-more,
.icon-chip {
  display: grid;
  width: 38px;
  height: 34px;
  place-items: center;
  border: 2px solid var(--ink);
  background: #fffdf4;
  box-shadow: 3px 3px 0 rgba(38, 50, 56, 0.14);
}

.tree-group {
  display: grid;
  gap: 5px;
}

.tree-folder,
.tree-file {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  min-width: 0;
  border: 0;
  background: transparent;
  padding: 6px 7px;
  text-align: left;
}

.tree-folder {
  color: var(--muted);
  font-weight: 900;
}

.tree-file {
  border: 1.5px solid transparent;
  font-size: 13px;
  transform: rotate(-0.12deg);
}

.tree-file span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tree-file:hover,
.tree-file.selected {
  border-color: rgba(38, 50, 56, 0.48);
  background: linear-gradient(transparent 52%, rgba(155, 211, 234, 0.62) 52%);
}

.main-workspace {
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 16px;
  min-width: 0;
}

.command-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px;
  animation: draw-in 480ms ease both;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 240px;
  padding: 0 12px;
  min-height: 42px;
  border: 2px solid var(--ink);
  background: #fffefa;
}

.search-box input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
}

.command-actions {
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.marker-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
