}

.marker-button:hover,
.icon-chip:hover,
.panel-title button:hover,
.tab-more:hover {
  background: linear-gradient(transparent 45%, rgba(255, 217, 120, 0.78) 45%);
  transform: rotate(-1deg) translateY(-1px);
}

.work-grid {
  display: grid;
  grid-template-columns: minmax(320px, 0.82fr) minmax(420px, 1.18fr);
  gap: 16px;
  min-height: 0;
}

.sketch-card {
  padding: 16px;
  animation: draw-in 520ms ease both, gentle-wobble 7s ease-in-out infinite;
}

.source-pane,
.editor-pane {
  min-height: 530px;
}

.source-stage {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 14px;
  margin-top: 16px;
  padding: 13px;
  border: 1.8px solid rgba(38, 50, 56, 0.55);
  background: rgba(255, 255, 255, 0.45);
}

.source-badge {
  display: grid;
  place-items: center;
  gap: 8px;
  min-height: 96px;
  border: 2px solid var(--ink);
  background: var(--blue);
  font-weight: 900;
  transform: rotate(-1.2deg);
}

.source-badge.audio {
  background: var(--green);
}

.source-badge.document {
  background: var(--yellow);
}

.progress-block {
  min-width: 0;
}

.progress-meta span {
  font-family: "Comic Sans MS", "Segoe Print", cursive;
  font-size: 22px;
  font-weight: 900;
}

.pencil-progress {
  height: 14px;
  margin: 12px 0;
  border: 2px solid var(--ink);
  background: repeating-linear-gradient(-12deg, #fffdf4 0 7px, #f4e8c5 7px 12px);
}

.pencil-progress span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--blue), var(--orange));
  animation: pencil-fill 850ms ease both;
}

.progress-block p {
  margin-bottom: 0;
  color: var(--muted);
  font-size: 13px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.segment-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.segment-row {
  display: grid;
  grid-template-columns: 18px 66px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 11px;
  border: 1.8px solid rgba(38, 50, 56, 0.62);
  background: #fffdf4;
  text-align: left;
}

.segment-row small {
  grid-column: 2 / -1;
  color: var(--muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tone-blue {
  background: linear-gradient(90deg, rgba(155, 211, 234, 0.42), #fffdf4 52%);
}

.tone-yellow {
  background: linear-gradient(90deg, rgba(255, 217, 120, 0.45), #fffdf4 52%);
}

.tone-green {
  background: linear-gradient(90deg, rgba(166, 221, 179, 0.45), #fffdf4 52%);
}

.editor-pane {
  padding-top: 0;
}

.editor-tabs {
  display: flex;
  align-items: end;
  gap: 7px;
  margin: -2px -2px 18px;
  padding-top: 8px;
  border-bottom: 2px solid var(--ink);
}

.paper-tab {
  min-height: 38px;
  padding: 0 18px;
  border: 2px solid var(--ink);
  border-bottom: 0;
  background: #fffdf4;
  font-weight: 900;
  transform: rotate(-0.8deg);
}

.paper-tab.active {
  background: var(--yellow);
}

.tab-more {
  margin-left: auto;
  margin-bottom: 5px;
}

.note-header {
  padding-bottom: 14px;
  border-bottom: 1.8px dashed rgba(38, 50, 56, 0.28);
}

.tag-row {
  gap: 7px;
  flex-wrap: wrap;
  margin-top: 9px;
}

.tag-row span {
  padding: 3px 8px;
  background: linear-gradient(transparent 45%, rgba(155, 211, 234, 0.75) 45%);
  font-weight: 900;
}

.markdown-editor {
  min-height: 330px;
  margin-top: 16px;
  padding: 18px 20px;
  border-left: 4px solid var(--pink);
  outline: 0;
  background:
    linear-gradient(rgba(70, 100, 130, 0.12) 1px, transparent 1px) 0 16px / 100% 30px,
    #fffefa;
  line-height: 1.72;
}

.markdown-editor p {
  margin-bottom: 13px;
}

.bottom-shelf {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.queue-card {
  min-height: 172px;
}

.section-title.compact h3 {
  font-size: 17px;
}

.section-title.compact span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
}

.queue-list,
.note-list,
.backlink-list,
.task-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.queue-item,
.note-row {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  width: 100%;
  padding: 8px;
  border: 1.5px solid transparent;
  background: rgba(255, 255, 255, 0.42);
  text-align: left;
}

.queue-item span,
.note-row span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.queue-item small,
.note-row small {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
}

.queue-item:hover,
.queue-item.active,
.note-row:hover,
.note-row.active {
  border-color: rgba(38, 50, 56, 0.5);
  background: linear-gradient(transparent 52%, rgba(255, 217, 120, 0.6) 52%);
}

.context-card {
  padding: 13px;
  border: 1.8px solid rgba(38, 50, 56, 0.55);
  background: rgba(255, 255, 255, 0.42);
}

dl {
  display: grid;
  gap: 8px;
  margin: 0;
}

dl div {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr);
  gap: 8px;
}

dt {
  color: var(--muted);
  font-weight: 900;
}

dd {
  margin: 0;
  overflow-wrap: anywhere;
  font-weight: 800;
}

.backlink-list button {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 31px;
  border: 0;
  background: transparent;
  text-align: left;
}

.backlink-list button:hover {
  background: linear-gradient(transparent 50%, rgba(155, 211, 234, 0.65) 50%);
}

.mini-graph {
  position: relative;
  min-height: 170px;
  overflow: hidden;
  background:
    linear-gradient(rgba(38, 50, 56, 0.09) 1px, transparent 1px) 0 0 / 100% 34px;
}

.mini-graph::before,
.mini-graph::after {
  content: "";
  position: absolute;
  left: 44px;
  right: 34px;
  top: 83px;
  border-top: 2px dashed rgba(38, 50, 56, 0.5);
  transform: rotate(-8deg);
}

.mini-graph::after {
  top: 98px;
  transform: rotate(12deg);
}

.node {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 150px;
  padding: 7px 9px;
  border: 2px solid var(--ink);
  background: var(--paper-soft);
  font-size: 12px;
  font-weight: 900;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.node.center {
  left: 34px;
  top: 62px;
  background: var(--yellow);
  z-index: 1;
}

.node.n1 {
  right: 8px;
  top: 18px;
  background: var(--blue);
}

.node.n2 {
  right: 20px;
  bottom: 22px;
  background: var(--pink);
}

.node.n3 {
  left: 12px;
  bottom: 10px;
  background: var(--green);
}

.task-list label {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  font-size: 13px;
  font-weight: 800;
}

.status-note {
  gap: 8px;
  margin-top: auto;
  padding: 11px;
  border: 2px solid rgba(38, 50, 56, 0.52);
  background: #dcf4e3;
  font-size: 13px;
  font-weight: 900;
}

@keyframes draw-in {
  from {
    opacity: 0;
    clip-path: inset(0 100% 0 0);
    transform: translateY(8px) rotate(-0.4deg);
  }
  to {
    opacity: 1;
    clip-path: inset(0 0 0 0);
    transform: translateY(0) rotate(0deg);
  }
}

@keyframes gentle-wobble {
  0%,
  100% {
    rotate: 0deg;
  }
  50% {
    rotate: 0.18deg;
  }
}

@keyframes pencil-fill {
  from {
    width: 0;
  }
}

@media (max-width: 1280px) {
  .workspace-shell {
    grid-template-columns: 240px minmax(0, 1fr);
  }

  .context-panel {
    grid-column: 1 / -1;
    min-height: auto;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    align-items: start;
  }

  .context-panel > .panel-title,
  .context-panel > .status-note {
    grid-column: 1 / -1;
  }
}

@media (max-width: 980px) {
  .workspace-shell,
  .work-grid,
  .bottom-shelf {
    grid-template-columns: 1fr;
  }

  .left-rail,
  .context-panel {
    min-height: auto;
  }

  .context-panel {
    display: flex;
  }

  .command-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .search-box {
    min-width: 0;
  }
}

@media (max-width: 620px) {
  .workspace-shell {
    padding: 12px;
  }

  .bookmark-nav {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .source-stage,
  .segment-row {
    grid-template-columns: 1fr;
  }

  .segment-row small {
    grid-column: 1;
    white-space: normal;
  }

  .editor-tabs {
    overflow-x: auto;
  }

  .paper-tab {
    padding: 0 13px;
  }

  .queue-item,
  .note-row {
    grid-template-columns: 20px minmax(0, 1fr);
  }

  .queue-item small,
  .note-row small {
    grid-column: 2;
  }
}

